export default RadialRingBar;

"use client";

import { memo, type ReactNode, useId, useMemo } from "react";
import {
  type PatternPresetId,
  patternPresetTileSize,
  renderPatternPreset,
} from "./pattern-preset";
import { radialLabelFontSize } from "./radial-axis";
import {
  type RadialSeries,
  radialNumberAt,
  useRadialChart,
} from "./radial-chart";
import {
  computeRadialDotGrid,
  createRadialRowScale,
  type RadialDotLayout,
  type RadialDotSlot,
  radialDotRowRadius,
  stackRadialRows,
} from "./radial-dot-bar-layout";
import { polarToCartesian } from "./radial-geometry";
import { radialSeriesColor } from "./radial-series-color";

/**
 * Pattern fill for a series' (or the ghost layer's) dots, built from the
 * shared pattern presets (`renderPatternPreset`).
 */
export interface RadialDotPattern {
  /** Pattern preset. Default: "diagonal" */
  preset?: PatternPresetId;
  /**
   * Custom fill instead of a preset — e.g. `url(#my-pattern)` for a pattern
   * you render yourself. Ignores `preset`, `color`, `scale` and `units`.
   */
  fill?: string;
  /** Stripe / dot color. Default: the series color */
  color?: string;
  /** Pattern tile scale (1 = preset size). Default: 1 */
  scale?: number;
  /** Stripe stroke width in px. Default: preset width × scale */
  strokeWidth?: number;
  /** Tile background behind the stripes. Default: none (transparent) */
  background?: string;
  /** Ring around each dot so patterned dots read as circles. Default: `color`; "none" hides it */
  stroke?: string;
  /** Ring width in px. Default: 1 */
  ringWidth?: number;
  /**
   * - `dot`: the tile is fitted to each dot so every dot shows the same,
   *   centred stripes.
   * - `chart`: one continuous texture across the chart, seen through the dots.
   * Default: "dot"
   */
  units?: "dot" | "chart";
}

export interface RadialDotBarAnnotation {
  /** Bin index the label points at */
  index: number;
  label: string;
  /**
   * Text color. Default: the first `emphasize` series' color, else the
   * color of the series at the bin's tip
   */
  color?: string;
}

export interface RadialDotBarProps {
  /**
   * Datum key of a comparison value (e.g. yesterday's total), drawn as dim
   * "ghost" dots in bins where no series has a value (the rest of the day).
   */
  ghostDataKey?: string;
  /** Ghost dot color. Default: var(--foreground) */
  ghostColor?: string;
  /** Ghost dot opacity. Default: 0.22 */
  ghostOpacity?: number;
  /** Value mapped to the outermost row. Default: largest stack / ghost value */
  maxValue?: number;
  /** Concentric rows across the value band. Default: 14 */
  rows?: number;
  /** Dot placement on each row. Default: "grid" (even density) */
  layout?: RadialDotLayout;
  /** Dot diameter as a fraction of the row spacing. Default: 0.44 */
  dotSize?: number;
  /** Ghost dot diameter as a fraction of the row spacing. Default: 0.26 */
  ghostDotSize?: number;
  /** Fraction of the rows over which `rampFrom` series reach full opacity. Default: 0.5 */
  rampExtent?: number;
  /** Callout labels outside a bin's tip */
  annotations?: RadialDotBarAnnotation[];
  /** Opacity of other series while a legend item is hovered. Default: 0.2 */
  fadedOpacity?: number;
  /**
   * Pattern fills keyed by series `dataKey` (use `"ghost"` for the ghost
   * layer). Pass a preset id (e.g. `"diagonal"`) or a {@link RadialDotPattern}.
   * Series without an entry stay solid.
   */
  patterns?: Record<string, PatternPresetId | RadialDotPattern>;
}

const ENTER_SPREAD_S = 0.75;
const ENTER_ROW_STEP_S = 0.03;
const ENTER_DURATION_S = 0.36;

interface DotSpec {
  key: string;
  x: number;
  y: number;
  r: number;
  opacity: number;
  delay: number;
}

interface DotGroup {
  key: string;
  /** Series index, or -1 for the ghost layer */
  seriesIndex: number;
  fill: string;
  stroke?: string;
  strokeWidth?: number;
  dots: DotSpec[];
}

interface ResolvedDotFill {
  fill: string;
  stroke?: string;
  strokeWidth?: number;
  /** Ring inset so the outer edge of the ring matches the dot size */
  inset: number;
  defs: ReactNode;
}

/** Largest tile count ≥ 1 that keeps the tile near the preset size. */
function fitTileCount(diameter: number, tile: number): number {
  return Math.max(1, Math.round(diameter / Math.max(0.5, tile)));
}

function resolveDotFill({
  pattern,
  color,
  id,
  diameter,
}: {
  pattern: PatternPresetId | RadialDotPattern | undefined;
  color: string;
  id: string;
  diameter: number;
}): ResolvedDotFill {
  if (pattern === undefined || pattern === "none") {
    return { fill: color, inset: 0, defs: null };
  }
  const spec: RadialDotPattern =
    typeof pattern === "string" ? { preset: pattern } : pattern;
  const patternColor = spec.color ?? color;
  const stroke = spec.stroke ?? patternColor;
  const ringWidth = stroke === "none" ? 0 : (spec.ringWidth ?? 1);
  const ring = {
    stroke: ringWidth > 0 ? stroke : undefined,
    strokeWidth: ringWidth > 0 ? ringWidth : undefined,
    inset: ringWidth / 2,
  };
  if (spec.fill) {
    return { fill: spec.fill, defs: null, ...ring };
  }
  const preset = spec.preset ?? "diagonal";
  if (preset === "none") {
    return { fill: patternColor, defs: null, ...ring };
  }
  const baseScale = spec.scale ?? 1;
  const options = {
    color: patternColor,
    strokeWidth: spec.strokeWidth,
    tileBackground: spec.background,
  };
  if ((spec.units ?? "dot") === "chart" || diameter <= 0) {
    return {
      fill: `url(#${id})`,
      defs: renderPatternPreset(preset, id, { ...options, scale: baseScale }),
      ...ring,
    };
  }
  // Fit a whole number of tiles across the dot, then re-anchor the tile to
  // each dot's bounding box so every dot shows identical, centred stripes.
  const tile = patternPresetTileSize(preset, baseScale).width;
  const count = fitTileCount(diameter, tile);
  const scale = (baseScale * diameter) / (count * tile);
  const baseId = `${id}-base`;
  return {
    fill: `url(#${id})`,
    defs: (
      <>
        {renderPatternPreset(preset, baseId, { ...options, scale })}
        <defs>
          <pattern
            height={1 / count}
            href={`#${baseId}`}
            id={id}
            patternUnits="objectBoundingBox"
            width={1 / count}
            x={0}
            y={0}
          />
        </defs>
      </>
    ),
    ...ring,
  };
}

const DotGroups = memo(function DotGroups({
  groups,
  revealed,
  animate,
  hoveredSeries,
  fadedOpacity,
}: {
  groups: DotGroup[];
  revealed: boolean;
  animate: boolean;
  hoveredSeries: number | null;
  fadedOpacity: number;
}) {
  return (
    <g pointerEvents="none">
      {groups.map((group) => {
        const dimmed =
          hoveredSeries !== null && hoveredSeries !== group.seriesIndex;
        return (
          <g
            fill={group.fill}
            key={group.key}
            stroke={group.stroke}
            strokeWidth={group.strokeWidth}
            style={{
              opacity: dimmed ? fadedOpacity : 1,
              transition: "opacity 0.15s ease-out",
            }}
          >
            {group.dots.map((dot) => (
              <circle
                cx={dot.x}
                cy={dot.y}
                key={dot.key}
                r={dot.r}
                style={{
                  opacity: revealed ? dot.opacity : 0,
                  transform: revealed ? undefined : "scale(0)",
                  transformBox: "fill-box",
                  transformOrigin: "center",
                  transition: animate
                    ? `opacity ${ENTER_DURATION_S}s ease-out ${dot.delay}s, transform ${ENTER_DURATION_S}s cubic-bezier(0.2, 0.8, 0.2, 1) ${dot.delay}s`
                    : undefined,
                }}
              />
            ))}
          </g>
        );
      })}
    </g>
  );
});

/**
 * Default annotation color: the first `emphasize` series, else the topmost
 * series with dots in the annotated bin.
 */
function annotationSeriesColor(
  series: RadialSeries[],
  ends: number[] | undefined
): string {
  let index = series.findIndex((s) => s.emphasize);
  if (index < 0 && ends) {
    for (let i = ends.length - 1; i >= 0; i--) {
      if ((ends[i] ?? 0) > (i > 0 ? (ends[i - 1] ?? 0) : 0)) {
        index = i;
        break;
      }
    }
  }
  return radialSeriesColor(series[index], Math.max(0, index));
}

/**
 * Radial dot bars for {@link RadialChart}: every bin is a stacked column of
 * dots on concentric rows (innermost series first), cascading outward on
 * enter like `BarSquares`. A radial scale keeps the dot count proportional to
 * the value with the default `grid` layout.
 */
export function RadialDotBar({
  ghostDataKey,
  ghostColor = "var(--foreground)",
  ghostOpacity = 0.22,
  maxValue: maxValueProp,
  rows = 14,
  layout = "grid",
  dotSize = 0.44,
  ghostDotSize = 0.26,
  rampExtent = 0.5,
  annotations,
  fadedOpacity = 0.2,
  patterns,
}: RadialDotBarProps) {
  const patternIdBase = `radial-dot-pattern-${useId().replace(/:/g, "")}`;
  const {
    data,
    series,
    binCount,
    radius,
    layout: ringLayout,
    innerRadius,
    outerRadius,
    futureBins,
    hoveredSeries,
    revealed,
    animate,
    binAngle,
  } = useRadialChart();

  const maxValue = useMemo(() => {
    if (maxValueProp !== undefined) {
      return maxValueProp;
    }
    let max = 0;
    data.forEach((d, i) => {
      const value = futureBins[i]
        ? ((ghostDataKey ? radialNumberAt(d, ghostDataKey) : 0) ?? 0)
        : series.reduce(
            (sum, s) => sum + Math.max(0, radialNumberAt(d, s.dataKey) ?? 0),
            0
          );
      max = Math.max(max, value);
    });
    return max;
  }, [maxValueProp, data, series, futureBins, ghostDataKey]);

  const spacing = rows > 0 ? (outerRadius - innerRadius) / rows : 0;

  const grid = useMemo(
    () =>
      computeRadialDotGrid({
        binCount,
        baseRadius: innerRadius,
        spacing,
        rows,
        layout,
      }),
    [binCount, innerRadius, spacing, rows, layout]
  );

  const toRows = useMemo(
    () =>
      createRadialRowScale({
        maxValue,
        baseRadius: innerRadius,
        spacing,
        rows,
      }),
    [maxValue, innerRadius, spacing, rows]
  );

  /** Exclusive end row of each series per bin (future bins: the ghost). */
  const stackEnds = useMemo(
    () =>
      data.map((d, i) => {
        if (futureBins[i]) {
          const ghost = ghostDataKey
            ? (radialNumberAt(d, ghostDataKey) ?? 0)
            : 0;
          return stackRadialRows([ghost], toRows, rows);
        }
        return stackRadialRows(
          series.map((s) => radialNumberAt(d, s.dataKey) ?? 0),
          toRows,
          rows
        );
      }),
    [data, futureBins, ghostDataKey, series, toRows, rows]
  );

  const fills = useMemo(() => {
    const dotDiameter = spacing * dotSize;
    const seriesFills = series.map((s, seriesIndex) =>
      resolveDotFill({
        pattern: patterns?.[s.dataKey],
        color: radialSeriesColor(s, seriesIndex),
        id: `${patternIdBase}-${seriesIndex}`,
        diameter: dotDiameter,
      })
    );
    const ghostFill = resolveDotFill({
      pattern: patterns?.ghost,
      color: ghostColor,
      id: `${patternIdBase}-ghost`,
      diameter: spacing * ghostDotSize,
    });
    return { series: seriesFills, ghost: ghostFill };
  }, [
    spacing,
    dotSize,
    ghostDotSize,
    series,
    patterns,
    ghostColor,
    patternIdBase,
  ]);

  const groups = useMemo((): DotGroup[] => {
    if (spacing <= 0) {
      return [];
    }
    const seriesGroups: DotGroup[] = series.map((s, seriesIndex) => {
      const f = fills.series[seriesIndex];
      return {
        key: `series-${s.dataKey}`,
        seriesIndex,
        fill: f?.fill ?? radialSeriesColor(s, seriesIndex),
        stroke: f?.stroke,
        strokeWidth: f?.strokeWidth,
        dots: [],
      };
    });
    const ghostGroup: DotGroup = {
      key: "ghost",
      seriesIndex: -1,
      fill: fills.ghost.fill,
      stroke: fills.ghost.stroke,
      strokeWidth: fills.ghost.strokeWidth,
      dots: [],
    };
    const seriesR = series.map((_, i) =>
      Math.max(0, (spacing * dotSize) / 2 - (fills.series[i]?.inset ?? 0))
    );
    const ghostR = Math.max(
      0,
      (spacing * ghostDotSize) / 2 - fills.ghost.inset
    );
    const rampRows = Math.max(1, rows * rampExtent);

    const seriesDot = (slot: RadialDotSlot, ends: number[]) => {
      const seriesIndex = ends.findIndex((end) => slot.row < end);
      const s = series[seriesIndex];
      const group = seriesGroups[seriesIndex];
      if (!(s && group)) {
        return null;
      }
      const rampFrom = s.rampFrom ?? 1;
      const ramp = rampFrom + (1 - rampFrom) * Math.min(1, slot.row / rampRows);
      return {
        group,
        r: seriesR[seriesIndex] ?? 0,
        opacity: (s.opacity ?? 1) * ramp,
      };
    };

    grid.forEach((slots, bin) => {
      const ends = stackEnds[bin] ?? [];
      const binDelay = (bin / Math.max(1, binCount)) * ENTER_SPREAD_S;
      for (const slot of slots) {
        let target: { group: DotGroup; r: number; opacity: number } | null =
          null;
        if (futureBins[bin]) {
          target =
            (ends[0] ?? 0) > slot.row
              ? { group: ghostGroup, r: ghostR, opacity: ghostOpacity }
              : null;
        } else {
          target = seriesDot(slot, ends);
        }
        target?.group.dots.push({
          key: `${bin}-${slot.row}-${slot.angle.toFixed(4)}`,
          x: slot.x,
          y: slot.y,
          r: target.r,
          opacity: target.opacity,
          delay: binDelay + slot.row * ENTER_ROW_STEP_S,
        });
      }
    });

    return [ghostGroup, ...seriesGroups];
  }, [
    spacing,
    series,
    ghostColor,
    dotSize,
    ghostDotSize,
    rows,
    rampExtent,
    grid,
    stackEnds,
    binCount,
    futureBins,
    ghostOpacity,
    fills,
  ]);

  const fontSize = radialLabelFontSize(radius);

  return (
    <g>
      {fills.ghost.defs}
      {fills.series.map((f, i) => (
        <g key={series[i]?.dataKey ?? i}>{f.defs}</g>
      ))}
      <DotGroups
        animate={animate}
        fadedOpacity={fadedOpacity}
        groups={groups}
        hoveredSeries={hoveredSeries}
        revealed={revealed}
      />
      {annotations?.map((annotation) => {
        const ends = stackEnds[annotation.index];
        const annotationColor =
          annotation.color ?? annotationSeriesColor(series, ends);
        const tipRow = Math.max(0, (ends?.at(-1) ?? 1) - 1);
        const tipRadius = radialDotRowRadius(innerRadius, spacing, tipRow);
        const angle = binAngle(annotation.index);
        const p = polarToCartesian(
          angle,
          Math.max(
            tipRadius + spacing * 2.5,
            radius * ringLayout.axisLabel * 1.02
          )
        );
        const sin = Math.sin(angle);
        let anchor: "start" | "middle" | "end" = "middle";
        if (sin > 0.25) {
          anchor = "start";
        } else if (sin < -0.25) {
          anchor = "end";
        }
        return (
          <text
            className="font-mono"
            dominantBaseline="central"
            fill={annotationColor}
            fontSize={fontSize}
            key={`annotation-${annotation.index}-${annotation.label}`}
            pointerEvents="none"
            style={{
              opacity: revealed ? 1 : 0,
              transition: animate
                ? `opacity 0.4s ease-out ${ENTER_SPREAD_S}s`
                : undefined,
            }}
            textAnchor={anchor}
            x={p.x}
            y={p.y}
          >
            {annotation.label}
          </text>
        );
      })}
    </g>
  );
}

RadialDotBar.displayName = "RadialDotBar";

export default RadialDotBar;

import { createRadialScale, polarToCartesian, TAU } from "./radial-geometry";

/**
 * How dots are placed on each concentric row.
 * - `grid`: constant arc spacing, so outer rows hold more dots and the dot
 *   density stays even (area ∝ value with a radial scale).
 * - `columns`: one dot per bin on every row — strict radial columns.
 */
export type RadialDotLayout = "grid" | "columns";

export interface RadialDotSlot {
  /** Row index, 0 = innermost */
  row: number;
  /** Bin (time slot) the dot belongs to */
  bin: number;
  /** Angle in radians, 0 = 12 o'clock, clockwise */
  angle: number;
  radius: number;
  x: number;
  y: number;
}

export interface RadialDotGridInput {
  binCount: number;
  /** Radius of the band's base (row 0 sits half a step outside it) */
  baseRadius: number;
  /** Centre-to-centre spacing between rows (and between dots on a row) */
  spacing: number;
  rows: number;
  layout?: RadialDotLayout;
}

/** Radius of row `row` (dot centre). */
export function radialDotRowRadius(
  baseRadius: number,
  spacing: number,
  row: number
): number {
  return baseRadius + spacing * (row + 0.5);
}

/**
 * Every dot slot of the polar grid, grouped by bin and sorted by row
 * (innermost first). Bins with no slot on a row simply skip that row.
 */
export function computeRadialDotGrid({
  binCount,
  baseRadius,
  spacing,
  rows,
  layout = "grid",
}: RadialDotGridInput): RadialDotSlot[][] {
  const byBin: RadialDotSlot[][] = Array.from({ length: binCount }, () => []);
  if (binCount <= 0 || spacing <= 0 || rows <= 0) {
    return byBin;
  }

  for (let row = 0; row < rows; row++) {
    const radius = radialDotRowRadius(baseRadius, spacing, row);
    const count =
      layout === "columns"
        ? binCount
        : Math.max(1, Math.round((TAU * radius) / spacing));

    for (let j = 0; j < count; j++) {
      const angle = ((j + 0.5) / count) * TAU;
      const bin = Math.min(binCount - 1, Math.floor((angle / TAU) * binCount));
      const { x, y } = polarToCartesian(angle, radius);
      byBin[bin]?.push({ row, bin, angle, radius, x, y });
    }
  }

  return byBin;
}

/**
 * Value → row count, using a radial scale so the dot area (and with the `grid`
 * layout, the dot count) grows linearly with the value.
 */
export function createRadialRowScale({
  maxValue,
  baseRadius,
  spacing,
  rows,
}: {
  maxValue: number;
  baseRadius: number;
  spacing: number;
  rows: number;
}): (value: number) => number {
  const radial = createRadialScale({
    maxValue,
    innerRadius: baseRadius,
    outerRadius: baseRadius + rows * spacing,
  });
  return (value: number) => {
    if (!(value > 0)) {
      return 0;
    }
    return Math.max(0, Math.round((radial(value) - baseRadius) / spacing));
  };
}

/**
 * Stacked row boundaries for one bin: `ends[i]` is the exclusive end row of
 * series `i`. Positive values always get at least one row.
 */
export function stackRadialRows(
  values: number[],
  toRows: (value: number) => number,
  maxRows: number
): number[] {
  const ends: number[] = [];
  let cumulative = 0;
  let previousEnd = 0;
  for (const value of values) {
    const v = value > 0 ? value : 0;
    cumulative += v;
    let end = toRows(cumulative);
    if (v > 0) {
      end = Math.max(end, previousEnd + 1);
    }
    end = Math.min(maxRows, Math.max(previousEnd, end));
    ends.push(end);
    previousEnd = end;
  }
  return ends;
}

"use client";

import {
  type CurveFactory,
  curveCatmullRom,
  curveCatmullRomClosed,
  lineRadial,
} from "d3-shape";
import { motion, type SpringOptions } from "motion/react";
import { memo, useId, useMemo } from "react";
import {
  createRadialEdgeLookup,
  type RadialDotMotion,
  RadialHoverDot,
  radialNumberAt,
  useRadialChart,
  useRadialDotAngle,
} from "./radial-chart";
import { createRadialScale, polarToCartesian } from "./radial-geometry";
import { radialSeriesColor } from "./radial-series-color";

export interface RadialLineProps {
  /**
   * Datum key plotted by this line. When it matches a `RadialChart` series the
   * line inherits its color / opacity and dims with the legend; any other key
   * (e.g. `"yesterday"`) is drawn as a comparison line.
   */
  dataKey: string;
  /** Stroke color. Default: the series color (else its palette slot), else var(--foreground) */
  stroke?: string;
  /** Stroke width in px. Default: 2 */
  strokeWidth?: number;
  /** Stroke opacity. Default: the series opacity, else 1 */
  strokeOpacity?: number;
  /**
   * Dash pattern — `true` for `strokeWidth` dashes with 3× gaps,
   * or any SVG `stroke-dasharray`. Default: solid
   */
  dash?: boolean | string;
  /**
   * d3 curve. Default: `curveCatmullRomClosed` for a closed loop, else
   * `curveCatmullRom` (smooth without overshooting the data)
   */
  curve?: CurveFactory;
  /** Join the last bin back to the first. Default: true when every bin has a value on a full circle */
  closed?: boolean;
  /**
   * Value mapped to the band top. Default: the chart's shared scale when
   * `RadialChart` has `maxValue`, else the largest value across every series
   * and this line
   */
  maxValue?: number;
  /** Point marker on the hovered bin, riding the line. Default: true */
  showMarkers?: boolean;
  /**
   * How the hover marker follows the pointer: locked to the crosshair (the
   * `RadialScrubber` spring), its own spring (`markerSpring`) or snapping to
   * the bin. Reduced motion always snaps. Default: "crosshair"
   */
  markerMotion?: RadialDotMotion;
  /** `markerMotion="spring"`: the marker's spring. Default: `{ stiffness: 240, damping: 24 }` */
  markerSpring?: SpringOptions;
  /** Marker at the line's last value ("now"). Default: true for open lines */
  showNowMarker?: boolean;
  /** Soft pulse around the "now" marker (off under reduced motion). Default: true */
  pulse?: boolean;
  /** Marker radius in px. Default: scales with the chart */
  markerRadius?: number;
  /** Opacity while another series is hovered in the legend. Default: 0.2 */
  fadedOpacity?: number;
  /** Delay before the clockwise draw starts, in seconds. Default: 0 */
  enterDelay?: number;
}

const DRAW_DURATION_S = 1.2;
const DRAW_EASE = "cubic-bezier(0.65, 0, 0.35, 1)";

interface Point {
  x: number;
  y: number;
}

const NowMarker = memo(function NowMarker({
  point,
  color,
  r,
  pulse,
  visible,
  animate,
  delay,
}: {
  point: Point;
  color: string;
  r: number;
  pulse: boolean;
  visible: boolean;
  animate: boolean;
  delay: number;
}) {
  return (
    <g
      style={{
        opacity: visible ? 1 : 0,
        transition: animate ? `opacity 0.3s ease-out ${delay}s` : undefined,
      }}
      transform={`translate(${point.x},${point.y})`}
    >
      {pulse ? (
        <motion.circle
          animate={{ scale: [1, 2.6], opacity: [0.35, 0] }}
          fill={color}
          r={r}
          style={{ transformBox: "fill-box", transformOrigin: "center" }}
          transition={{
            duration: 2,
            ease: "easeOut",
            repeat: Number.POSITIVE_INFINITY,
            repeatDelay: 0.4,
          }}
        />
      ) : null}
      <circle fill={color} fillOpacity={0.16} r={r * 2} />
      <circle
        fill={color}
        r={r}
        stroke="var(--background)"
        strokeWidth={Math.max(1.5, r * 0.5)}
      />
    </g>
  );
});

function isClosedLoop(isFullCircle: boolean, values: (number | null)[]) {
  return isFullCircle && values.every((v) => v !== null);
}

function ownRadialScale(
  maxValue: number,
  innerRadius: number,
  outerRadius: number
): (value: number) => number {
  const scale = createRadialScale({ maxValue, innerRadius, outerRadius });
  return (value) => scale(value) ?? innerRadius;
}

/** Edge lookup for the hover marker — the same curve as the drawn line. */
function lineEdgeLookup(
  values: (number | null)[],
  binAngle: (index: number) => number,
  scale: (value: number) => number,
  curve: CurveFactory
) {
  const indices = values.map((_, i) => i);
  return createRadialEdgeLookup((context) =>
    lineRadial<number>()
      .angle((i) => binAngle(i))
      .radius((i) => scale(values[i] ?? 0))
      .defined((i) => values[i] !== null)
      .curve(curve)
      .context(context)(indices)
  );
}

function resolveDashArray(
  dash: boolean | string | undefined,
  strokeWidth: number
): string | undefined {
  if (dash === true) {
    return `${strokeWidth} ${strokeWidth * 3}`;
  }
  return typeof dash === "string" ? dash : undefined;
}

/**
 * Smooth radial line for {@link RadialChart}: one value per bin plotted
 * around the 24h clock (00 at the top, clockwise) with `d3.lineRadial`.
 * Draws itself clockwise on enter, ends in a "now" marker and marks the
 * hovered bin with a dot that rides the line, locked to the crosshair by
 * default (`markerMotion`). Dash it and give it a non-series `dataKey` for a comparison line
 * (e.g. yesterday).
 */
export function RadialLine({
  dataKey,
  stroke: strokeProp,
  strokeWidth = 2,
  strokeOpacity: strokeOpacityProp,
  dash,
  curve: curveProp,
  closed: closedProp,
  maxValue: maxValueProp,
  showMarkers = true,
  markerMotion = "crosshair",
  markerSpring,
  showNowMarker: showNowMarkerProp,
  pulse = true,
  markerRadius: markerRadiusProp,
  fadedOpacity = 0.2,
  enterDelay = 0,
}: RadialLineProps) {
  const {
    data,
    series,
    binCount,
    radius,
    innerRadius,
    outerRadius,
    hoveredIndex,
    hoveredSeries,
    revealed,
    animate,
    reducedMotion,
    binAngle,
    isFullCircle,
    sharedValueScale,
    valueScale,
  } = useRadialChart();
  const maskId = `radial-line-mask-${useId().replace(/:/g, "")}`;

  const seriesIndex = series.findIndex((s) => s.dataKey === dataKey);
  const seriesConfig = seriesIndex >= 0 ? series[seriesIndex] : undefined;
  const stroke = strokeProp ?? radialSeriesColor(seriesConfig, seriesIndex);
  const strokeOpacity = strokeOpacityProp ?? seriesConfig?.opacity ?? 1;

  const values = useMemo(
    () => data.map((d) => radialNumberAt(d, dataKey)),
    [data, dataKey]
  );

  const maxValue = useMemo(() => {
    if (maxValueProp !== undefined) {
      return maxValueProp;
    }
    let max = 0;
    for (const d of data) {
      for (const key of [dataKey, ...series.map((s) => s.dataKey)]) {
        max = Math.max(max, radialNumberAt(d, key) ?? 0);
      }
    }
    return max;
  }, [maxValueProp, data, dataKey, series]);

  const scale = useMemo(
    () =>
      maxValueProp === undefined && sharedValueScale
        ? valueScale
        : ownRadialScale(maxValue, innerRadius, outerRadius),
    [
      maxValueProp,
      sharedValueScale,
      valueScale,
      maxValue,
      innerRadius,
      outerRadius,
    ]
  );

  const closed = closedProp ?? isClosedLoop(isFullCircle, values);
  const curve = curveProp ?? (closed ? curveCatmullRomClosed : curveCatmullRom);

  const pathD = useMemo(() => {
    if (binCount === 0 || outerRadius <= 0) {
      return null;
    }
    const indices = values.map((_, i) => i);
    const generator = lineRadial<number>()
      .angle((i) => binAngle(i))
      .radius((i) => scale(values[i] ?? 0))
      .defined((i) => values[i] !== null)
      .curve(curve);
    return generator(indices);
  }, [binCount, outerRadius, values, binAngle, scale, curve]);

  const edge = useMemo(
    () =>
      showMarkers && pathD
        ? lineEdgeLookup(values, binAngle, scale, curve)
        : null,
    [showMarkers, pathD, values, binAngle, scale, curve]
  );
  const markerAngle = useRadialDotAngle(markerMotion, markerSpring);

  const pointAt = (index: number | null): Point | null => {
    if (index === null) {
      return null;
    }
    const value = values[index];
    if (value === null || value === undefined) {
      return null;
    }
    return polarToCartesian(binAngle(index), scale(value));
  };

  const lastIndex = useMemo(() => {
    for (let i = values.length - 1; i >= 0; i--) {
      if (values[i] !== null) {
        return i;
      }
    }
    return null;
  }, [values]);

  const showNowMarker = showNowMarkerProp ?? !closed;
  const markerRadius = markerRadiusProp ?? Math.max(3.5, radius * 0.016);
  const nowPoint = showNowMarker ? pointAt(lastIndex) : null;
  // Only while the hovered bin has a value on this line.
  const markerLookup = pointAt(hoveredIndex) ? edge : null;

  const dashArray = resolveDashArray(dash, strokeWidth);

  const dimmed = hoveredSeries !== null && hoveredSeries !== seriesIndex;
  const drawEnd = enterDelay + DRAW_DURATION_S;

  if (!pathD) {
    return null;
  }

  return (
    <g
      pointerEvents="none"
      style={{
        opacity: dimmed ? fadedOpacity : 1,
        transition: "opacity 0.15s ease-out",
      }}
    >
      {animate ? (
        <defs>
          <mask
            height={radius * 2}
            id={maskId}
            maskUnits="userSpaceOnUse"
            width={radius * 2}
            x={-radius}
            y={-radius}
          >
            <path
              d={pathD}
              fill="none"
              pathLength={1}
              stroke="white"
              strokeDasharray="1 1"
              strokeLinecap="butt"
              strokeWidth={strokeWidth + 6}
              style={{
                strokeDashoffset: revealed ? 0 : 1,
                transition: `stroke-dashoffset ${DRAW_DURATION_S}s ${DRAW_EASE} ${enterDelay}s`,
              }}
            />
          </mask>
        </defs>
      ) : null}

      <path
        d={pathD}
        fill="none"
        mask={animate ? `url(#${maskId})` : undefined}
        stroke={stroke}
        strokeDasharray={dashArray}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeOpacity={strokeOpacity}
        strokeWidth={strokeWidth}
      />

      {nowPoint ? (
        <NowMarker
          animate={animate}
          color={stroke}
          delay={drawEnd}
          point={nowPoint}
          pulse={pulse && !reducedMotion}
          r={markerRadius}
          visible={revealed}
        />
      ) : null}

      {markerLookup ? (
        <RadialHoverDot
          angle={markerAngle}
          fill={stroke}
          fillOpacity={Math.max(strokeOpacity, 0.5)}
          lookup={markerLookup}
          r={markerRadius}
          stroke="var(--background)"
          strokeWidth={Math.max(1.5, markerRadius * 0.5)}
        />
      ) : null}
    </g>
  );
}

RadialLine.displayName = "RadialLine";

export default RadialLine;

"use client";

import {
  areaRadial,
  type CurveFactory,
  curveBasis,
  curveBasisClosed,
  curveCatmullRom,
  curveCatmullRomClosed,
  curveLinear,
  curveLinearClosed,
  lineRadial,
} from "d3-shape";
import {
  animate as animateValue,
  type MotionValue,
  type SpringOptions,
  useMotionValue,
} from "motion/react";
import { memo, useEffect, useId, useMemo, useRef } from "react";
import {
  createRadialEdgeLookup,
  type RadialDotMotion,
  type RadialEdgeLookup,
  RadialHoverDot,
  radialNumberAt,
  useRadialChart,
  useRadialDotAngle,
} from "./radial-chart";
import { createRadialScale, radialWedgePath } from "./radial-geometry";
import { radialSeriesColor } from "./radial-series-color";

export type RadialAreaCurve = "catmullRom" | "basis" | "linear";

export type RadialAreaStroke = "outer" | "both" | "none";

export interface RadialAreaProps {
  /**
   * Draw a single area for this datum key (it need not be a chart series;
   * a matching series supplies color, opacity and legend dimming). Omit to
   * draw every chart series.
   */
  dataKey?: string;
  /** Inner edge of a single area — e.g. a min/max band. Default: the band base (0) */
  baseDataKey?: string;
  /** Series mode: stack series outward (true) or overlay them from the base. Default: true */
  stacked?: boolean;
  /** Fill / stroke color for a single area. Default: the series color (else its palette slot), else var(--foreground) */
  color?: string;
  /** Draw the fill. Default: true (false gives an outline-only line) */
  fill?: boolean;
  /** Fill opacity at the outer edge. Default: 0.32 */
  fillOpacity?: number;
  /**
   * Radial gradient: fraction of `fillOpacity` at the band base, rising to
   * the full value at the outer radius. Default: the series' `rampFrom`, else 0.25
   */
  rampFrom?: number;
  /** Which edges get a stroke. Default: "outer" */
  stroke?: RadialAreaStroke;
  /** Stroke width in px. Default: 1.5 */
  strokeWidth?: number;
  /** Stroke opacity. Default: 1 */
  strokeOpacity?: number;
  /** e.g. "4 4" for a dashed line */
  strokeDasharray?: string;
  /** Curve through the bin centers (closed when every bin has a value). Default: "catmullRom" */
  curve?: RadialAreaCurve;
  /**
   * Datum key of a comparison value (e.g. yesterday's total), drawn as a dim
   * "ghost" area with a dashed edge in bins where no series has a value.
   */
  ghostDataKey?: string;
  /** Ghost color. Default: var(--foreground) */
  ghostColor?: string;
  /** Ghost fill opacity (its stroke is twice this). Default: 0.1 */
  ghostOpacity?: number;
  /**
   * Value mapped to the outer radius. Default: the chart's shared scale when
   * `RadialChart` has `maxValue`, else the largest drawn value
   */
  maxValue?: number;
  /** Dot on the outer edge of the hovered bin, riding the edge. Default: true */
  activeDot?: boolean;
  /**
   * How the active dot follows the pointer: locked to the crosshair (the
   * `RadialScrubber` spring), its own spring (`activeDotSpring`) or snapping
   * to the bin. Reduced motion always snaps. Default: "crosshair"
   */
  activeDotMotion?: RadialDotMotion;
  /** `activeDotMotion="spring"`: the dot's spring. Default: `{ stiffness: 240, damping: 24 }` */
  activeDotSpring?: SpringOptions;
  /** Opacity of other series while a legend item is hovered. Default: 0.2 */
  fadedOpacity?: number;
}

const CURVES: Record<
  RadialAreaCurve,
  { open: CurveFactory; closed: CurveFactory }
> = {
  catmullRom: { open: curveCatmullRom, closed: curveCatmullRomClosed },
  basis: { open: curveBasis, closed: curveBasisClosed },
  linear: { open: curveLinear, closed: curveLinearClosed },
};

/** Clockwise sweep — matches `RadialDotBar`'s cascade. */
const ENTER_SPREAD_S = 0.75;
/** Rise time of each bin from the band base. */
const ENTER_DURATION_S = 0.5;
const ENTER_TOTAL_S = ENTER_SPREAD_S + ENTER_DURATION_S;

interface AreaPoint {
  angle: number;
  /** Bin index (drives the enter delay) */
  index: number;
  inner: number;
  outer: number;
}

interface AreaLayer {
  key: string;
  /** Series index, -1 when not a series, -2 for the ghost */
  seriesIndex: number;
  color: string;
  fill: boolean;
  fillOpacity: number;
  rampFrom: number;
  stroke: RadialAreaStroke;
  strokeOpacity: number;
  strokeDasharray?: string;
  /** Contiguous runs of points; `closed` runs wrap the full turn */
  runs: { points: AreaPoint[]; closed: boolean }[];
  /** Runs the edge strokes follow (stacked series skip zero-height bins) */
  strokeRuns: { points: AreaPoint[]; closed: boolean }[];
  /** Stroked point per bin (null where there is no edge) for the active dot */
  byBin: (AreaPoint | null)[];
}

interface RawLayer {
  key: string;
  seriesIndex: number;
  values: ({ lo: number; hi: number } | null)[];
}

function easeOutCubic(t: number): number {
  return 1 - (1 - t) ** 3;
}

/** Split per-bin points into runs; extend open runs to their bin edges. */
function toRuns(
  points: (AreaPoint | null)[],
  binStartAngle: (index: number) => number,
  isFullCircle: boolean
): AreaLayer["runs"] {
  if (isFullCircle && points.length > 0 && points.every((p) => p !== null)) {
    return [{ points: points as AreaPoint[], closed: true }];
  }
  const runs: AreaLayer["runs"] = [];
  let current: AreaPoint[] = [];
  const flush = () => {
    const first = current[0];
    const last = current.at(-1);
    if (first && last) {
      runs.push({
        closed: false,
        points: [
          { ...first, angle: binStartAngle(first.index) },
          ...current,
          { ...last, angle: binStartAngle(last.index + 1) },
        ],
      });
    }
    current = [];
  };
  for (const p of points) {
    if (p) {
      current.push(p);
    } else {
      flush();
    }
  }
  flush();
  return runs;
}

/** Points at enter progress `p` (0–1): each bin rises from the base after a clockwise delay. */
function grow(
  points: AreaPoint[],
  p: number,
  base: number,
  binCount: number
): AreaPoint[] {
  if (p >= 1) {
    return points;
  }
  const t = p * ENTER_TOTAL_S;
  return points.map((point) => {
    const delay = (point.index / Math.max(1, binCount)) * ENTER_SPREAD_S;
    const e = easeOutCubic(
      Math.min(1, Math.max(0, (t - delay) / ENTER_DURATION_S))
    );
    return {
      ...point,
      inner: base + (point.inner - base) * e,
      outer: base + (point.outer - base) * e,
    };
  });
}

/** Enter clip: a wedge sweeping from the start angle to the end angle. */
function wedgePath(
  p: number,
  r: number,
  startAngle: number,
  endAngle: number
): string {
  const t = Math.min(1, (p * ENTER_TOTAL_S) / ENTER_SPREAD_S);
  if (t >= 1 - 1e-4) {
    // Whole disc once the sweep is done (also covers partial arcs).
    return `M0,${-r}A${r},${r},0,1,1,0,${r}A${r},${r},0,1,1,0,${-r}Z`;
  }
  return radialWedgePath(
    r,
    startAngle,
    startAngle + (endAngle - startAngle) * t
  );
}

/** Keep an attribute in sync with the enter progress without re-rendering. */
function useProgressAttribute<T extends SVGElement>(
  progress: MotionValue<number>,
  attribute: string,
  compute: (p: number) => string
) {
  const ref = useRef<T>(null);
  useEffect(() => {
    const apply = (p: number) =>
      ref.current?.setAttribute(attribute, compute(p));
    apply(progress.get());
    return progress.on("change", apply);
  }, [progress, attribute, compute]);
  return ref;
}

const AreaLayerPaths = memo(function AreaLayerPaths({
  layer,
  progress,
  curve,
  base,
  binCount,
  gradientId,
}: {
  layer: AreaLayer;
  progress: MotionValue<number>;
  curve: RadialAreaCurve;
  base: number;
  binCount: number;
  gradientId: string;
}) {
  const paths = useMemo(() => {
    const factories = CURVES[curve];
    const build = (kind: "area" | "outer" | "inner", p: number): string =>
      (kind === "area" ? layer.runs : layer.strokeRuns)
        .map(({ points, closed }) => {
          const factory = closed ? factories.closed : factories.open;
          const grown = grow(points, p, base, binCount);
          if (kind === "area") {
            return (
              areaRadial<AreaPoint>()
                .angle((d) => d.angle)
                .innerRadius((d) => d.inner)
                .outerRadius((d) => d.outer)
                .curve(factory)(grown) ?? ""
            );
          }
          return (
            lineRadial<AreaPoint>()
              .angle((d) => d.angle)
              .radius((d) => (kind === "outer" ? d.outer : d.inner))
              .curve(factory)(grown) ?? ""
          );
        })
        .join("");
    return {
      area: (p: number) => build("area", p),
      outer: (p: number) => build("outer", p),
      inner: (p: number) => build("inner", p),
    };
  }, [layer, curve, base, binCount]);

  const areaRef = useProgressAttribute<SVGPathElement>(
    progress,
    "d",
    paths.area
  );
  const outerRef = useProgressAttribute<SVGPathElement>(
    progress,
    "d",
    paths.outer
  );
  const innerRef = useProgressAttribute<SVGPathElement>(
    progress,
    "d",
    paths.inner
  );
  const p = progress.get();

  return (
    <>
      {layer.fill ? (
        <path
          d={paths.area(p)}
          fill={`url(#${gradientId})`}
          fillRule="evenodd"
          ref={areaRef}
        />
      ) : null}
      {layer.stroke === "none" ? null : (
        <g
          fill="none"
          stroke={layer.color}
          strokeDasharray={layer.strokeDasharray}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeOpacity={layer.strokeOpacity}
        >
          <path d={paths.outer(p)} ref={outerRef} />
          {layer.stroke === "both" ? (
            <path d={paths.inner(p)} ref={innerRef} />
          ) : null}
        </g>
      )}
    </>
  );
});

function EnterClip({
  id,
  progress,
  radius,
  startAngle,
  endAngle,
}: {
  id: string;
  progress: MotionValue<number>;
  radius: number;
  startAngle: number;
  endAngle: number;
}) {
  const r = radius * 1.2;
  const compute = useMemo(
    () => (p: number) => wedgePath(p, r, startAngle, endAngle),
    [r, startAngle, endAngle]
  );
  const ref = useProgressAttribute<SVGPathElement>(progress, "d", compute);
  return (
    <clipPath id={id}>
      <path d={compute(progress.get())} ref={ref} />
    </clipPath>
  );
}

/**
 * Radial areas for {@link RadialChart} (d3 `areaRadial`): every chart series
 * stacked or overlaid from the band base, or a single `dataKey` area —
 * optionally a band between `baseDataKey` and `dataKey`. A smooth curve runs
 * through the bin centers and closes on itself when every bin has a value.
 * On enter the areas sweep in clockwise, each bin rising from the base.
 * The active dot rides each outer edge, locked to the crosshair by default
 * (`activeDotMotion`).
 */
export function RadialArea({
  dataKey,
  baseDataKey,
  stacked = true,
  color,
  fill = true,
  fillOpacity = 0.32,
  rampFrom,
  stroke = "outer",
  strokeWidth = 1.5,
  strokeOpacity = 1,
  strokeDasharray,
  curve = "catmullRom",
  ghostDataKey,
  ghostColor = "var(--foreground)",
  ghostOpacity = 0.1,
  maxValue: maxValueProp,
  activeDot = true,
  activeDotMotion = "crosshair",
  activeDotSpring,
  fadedOpacity = 0.2,
}: RadialAreaProps) {
  const {
    data,
    series,
    binCount,
    radius,
    innerRadius,
    outerRadius,
    futureBins,
    hoveredIndex,
    hoveredSeries,
    revealed,
    animate,
    binAngle,
    binStartAngle,
    isFullCircle,
    startAngle,
    endAngle,
    sharedValueScale,
    valueScale,
  } = useRadialChart();

  const uid = useId().replace(/:/g, "");
  const clipId = `radial-area-clip-${uid}`;

  // Raw values per layer (before scaling) ------------------------------------
  const raw = useMemo(() => {
    const layers: RawLayer[] = [];
    if (dataKey) {
      layers.push({
        key: `area-${dataKey}`,
        seriesIndex: series.findIndex((s) => s.dataKey === dataKey),
        values: data.map((d) => {
          const hi = radialNumberAt(d, dataKey);
          if (hi === null) {
            return null;
          }
          const lo = baseDataKey ? (radialNumberAt(d, baseDataKey) ?? 0) : 0;
          return { lo: Math.max(0, lo), hi: Math.max(0, hi) };
        }),
      });
    } else {
      const cumulative = data.map(() => 0);
      series.forEach((s, seriesIndex) => {
        layers.push({
          key: `series-${s.dataKey}`,
          seriesIndex,
          values: data.map((d, i) => {
            const v = radialNumberAt(d, s.dataKey);
            if (v === null) {
              return null;
            }
            const lo = stacked ? (cumulative[i] ?? 0) : 0;
            const hi = lo + Math.max(0, v);
            if (stacked) {
              cumulative[i] = hi;
            }
            return { lo, hi };
          }),
        });
      });
    }
    const ghost = ghostDataKey
      ? data.map((d, i) =>
          futureBins[i]
            ? (() => {
                const v = radialNumberAt(d, ghostDataKey);
                return v === null ? null : { lo: 0, hi: Math.max(0, v) };
              })()
            : null
        )
      : null;
    return { layers, ghost };
  }, [dataKey, baseDataKey, stacked, series, data, ghostDataKey, futureBins]);

  const maxValue = useMemo(() => {
    if (maxValueProp !== undefined) {
      return maxValueProp;
    }
    let max = 0;
    for (const layer of raw.layers) {
      for (const v of layer.values) {
        max = Math.max(max, v?.hi ?? 0);
      }
    }
    for (const v of raw.ghost ?? []) {
      max = Math.max(max, v?.hi ?? 0);
    }
    return max;
  }, [maxValueProp, raw]);

  const layers = useMemo((): AreaLayer[] => {
    if (outerRadius <= innerRadius) {
      return [];
    }
    const own = createRadialScale({ maxValue, innerRadius, outerRadius });
    const scale =
      maxValueProp === undefined && sharedValueScale
        ? valueScale
        : (value: number) => own(value) ?? innerRadius;
    const toPoints = (values: ({ lo: number; hi: number } | null)[]) =>
      values.map((v, index): AreaPoint | null =>
        v
          ? {
              index,
              angle: binAngle(index),
              inner: scale(v.lo),
              outer: scale(v.hi),
            }
          : null
      );

    const result: AreaLayer[] = [];
    if (raw.ghost) {
      const byBin = toPoints(raw.ghost);
      result.push({
        key: "ghost",
        seriesIndex: -2,
        color: ghostColor,
        fill: true,
        fillOpacity: ghostOpacity,
        rampFrom: 0.4,
        stroke: "outer",
        strokeOpacity: Math.min(1, ghostOpacity * 2.5),
        strokeDasharray: "3 4",
        runs: toRuns(byBin, binStartAngle, isFullCircle),
        strokeRuns: toRuns(byBin, binStartAngle, isFullCircle),
        byBin,
      });
    }
    for (const layer of raw.layers) {
      const s = series[layer.seriesIndex];
      const points = toPoints(layer.values);
      // A zero-height stacked series would trace the stack top it sits on.
      const byBin =
        dataKey || !stacked
          ? points
          : points.map((p) => (p && p.outer > p.inner ? p : null));
      result.push({
        key: layer.key,
        seriesIndex: layer.seriesIndex,
        color:
          (dataKey ? color : undefined) ??
          radialSeriesColor(s, layer.seriesIndex),
        fill,
        fillOpacity: fillOpacity * (s?.opacity ?? 1),
        rampFrom: rampFrom ?? s?.rampFrom ?? 0.25,
        stroke,
        strokeOpacity: strokeOpacity * (s?.opacity ?? 1),
        strokeDasharray,
        runs: toRuns(points, binStartAngle, isFullCircle),
        strokeRuns: toRuns(byBin, binStartAngle, isFullCircle),
        byBin,
      });
    }
    return result;
  }, [
    raw,
    series,
    maxValue,
    maxValueProp,
    sharedValueScale,
    valueScale,
    innerRadius,
    outerRadius,
    binAngle,
    binStartAngle,
    isFullCircle,
    dataKey,
    stacked,
    color,
    fill,
    fillOpacity,
    rampFrom,
    stroke,
    strokeOpacity,
    strokeDasharray,
    ghostColor,
    ghostOpacity,
  ]);

  // Enter progress -----------------------------------------------------------
  const progress = useMotionValue(animate ? 0 : 1);
  useEffect(() => {
    if (!animate) {
      progress.jump(1);
      return;
    }
    if (!revealed) {
      return;
    }
    const controls = animateValue(progress, 1, {
      duration: ENTER_TOTAL_S,
      ease: "linear",
    });
    return () => controls.stop();
  }, [animate, revealed, progress]);

  // Outer edge per layer, for the active dot to ride.
  const edges = useMemo(() => {
    const result = new Map<string, RadialEdgeLookup>();
    if (!activeDot) {
      return result;
    }
    const factories = CURVES[curve];
    for (const layer of layers) {
      if (layer.stroke === "none") {
        continue;
      }
      result.set(
        layer.key,
        createRadialEdgeLookup((context) => {
          for (const { points, closed } of layer.strokeRuns) {
            lineRadial<AreaPoint>()
              .angle((d) => d.angle)
              .radius((d) => d.outer)
              .curve(closed ? factories.closed : factories.open)
              .context(context)(points);
          }
        })
      );
    }
    return result;
  }, [activeDot, layers, curve]);
  const dotAngle = useRadialDotAngle(activeDotMotion, activeDotSpring);

  const dotR = Math.max(2.5, radius * 0.009);

  return (
    <g pointerEvents="none">
      <defs>
        <EnterClip
          endAngle={endAngle}
          id={clipId}
          progress={progress}
          radius={radius}
          startAngle={startAngle}
        />
        {layers.map((layer) => (
          <radialGradient
            cx={0}
            cy={0}
            gradientUnits="userSpaceOnUse"
            id={`radial-area-fill-${uid}-${layer.key}`}
            key={layer.key}
            r={outerRadius}
          >
            <stop
              offset={innerRadius / outerRadius}
              stopColor={layer.color}
              stopOpacity={layer.fillOpacity * layer.rampFrom}
            />
            <stop
              offset={1}
              stopColor={layer.color}
              stopOpacity={layer.fillOpacity}
            />
          </radialGradient>
        ))}
      </defs>
      <g clipPath={`url(#${clipId})`} strokeWidth={strokeWidth}>
        {layers.map((layer) => {
          const dimmed =
            hoveredSeries !== null && hoveredSeries !== layer.seriesIndex;
          return (
            <g
              key={layer.key}
              style={{
                opacity: dimmed ? fadedOpacity : 1,
                transition: "opacity 0.15s ease-out",
              }}
            >
              <AreaLayerPaths
                base={innerRadius}
                binCount={binCount}
                curve={curve}
                gradientId={`radial-area-fill-${uid}-${layer.key}`}
                layer={layer}
                progress={progress}
              />
            </g>
          );
        })}
      </g>
      {activeDot && hoveredIndex !== null
        ? layers.map((layer) => {
            const lookup = edges.get(layer.key);
            if (!(lookup && layer.byBin[hoveredIndex])) {
              return null;
            }
            const dimmed =
              hoveredSeries !== null && hoveredSeries !== layer.seriesIndex;
            return (
              <RadialHoverDot
                angle={dotAngle}
                fill={layer.color}
                key={`dot-${layer.key}`}
                lookup={lookup}
                opacity={dimmed ? fadedOpacity : 1}
                r={dotR}
                stroke="var(--background)"
                strokeWidth={1.5}
              />
            );
          })
        : null}
    </g>
  );
}

RadialArea.displayName = "RadialArea";

export default RadialArea;

"use client";

import { motion, type SpringOptions, useTransform } from "motion/react";
import { useId, useLayoutEffect } from "react";
import {
  RADIAL_CROSSHAIR_SPRING,
  useRadialAngleSpring,
  useRadialChart,
} from "./radial-chart";

/**
 * Scrubber line style.
 * - `solid`: a plain line
 * - `dashed`: a dashed line (see `dashArray`)
 * - `gradient`: fades in along its length, transparent at the center circle
 *   and full strength at the outer end
 */
export type RadialScrubberVariant = "solid" | "dashed" | "gradient";

export interface RadialScrubberProps {
  /** Line style. Default: "solid" */
  variant?: RadialScrubberVariant;
  /** `dashed` variant: SVG stroke-dasharray. Default: "4 4" */
  dashArray?: string;
  /** End dot. Default: true for solid and dashed, false for gradient */
  showDot?: boolean;
  /** Line + dot color. Default: var(--foreground) */
  color?: string;
  /** Line opacity. Default: 0.7 */
  lineOpacity?: number;
  /** Line width. Default: 1.5 */
  strokeWidth?: number;
  /** End dot radius in px. Default: scales with the chart */
  dotRadius?: number;
  /**
   * Where the scrubber rests when nothing is hovered: at "now" (the trailing
   * edge of `nowIndex`) or hidden. Default: "now" when the chart tracks now
   * (clock charts), else "hidden"
   */
  rest?: "now" | "hidden";
  /**
   * Spring toward the hovered bin. Hover dots locked to the crosshair
   * (`RadialLine` / `RadialArea` default) follow it too.
   * Default: `{ stiffness: 420, damping: 42 }`
   */
  spring?: SpringOptions;
}

/**
 * Line from the center circle outward ending in a solid dot (solid / dashed
 * lines) or fading in toward the outer end (gradient). At rest it marks
 * "now" (the trailing edge of `nowIndex`) on clock charts and is hidden
 * otherwise; while hovering it springs to the hovered bin, taking the short
 * way round across the start angle on full circles. Its spring is the
 * chart's crosshair: `RadialLine` / `RadialArea` hover dots ride along it.
 */
export function RadialScrubber({
  variant = "solid",
  dashArray = "4 4",
  showDot: showDotProp,
  color = "var(--foreground)",
  lineOpacity = 0.7,
  strokeWidth = 1.5,
  dotRadius,
  rest: restProp,
  spring: springOptions = RADIAL_CROSSHAIR_SPRING,
}: RadialScrubberProps) {
  const {
    binCount,
    nowIndex,
    trackNow,
    hoveredIndex,
    binAngle,
    binStartAngle,
    isFullCircle,
    orientation,
    centerRadius,
    radius,
    layout,
    reducedMotion,
    registerCrosshair,
  } = useRadialChart();

  const gradientId = `radial-scrubber-${useId().replace(/:/g, "")}`;
  const rest = restProp ?? (trackNow ? "now" : "hidden");
  const hidden = hoveredIndex === null && rest === "hidden";
  const angle =
    hoveredIndex === null
      ? binStartAngle(nowIndex + 1)
      : binAngle(hoveredIndex);

  const spring = useRadialAngleSpring({
    angle,
    hidden,
    isFullCircle,
    snap: reducedMotion,
    spring: springOptions,
  });

  // Hover dots locked to the crosshair follow this spring.
  const drawn = binCount > 0 && orientation !== "angular";
  useLayoutEffect(
    () => (drawn ? registerCrosshair(spring) : undefined),
    [drawn, registerCrosshair, spring]
  );

  const inner = centerRadius + 2;
  const outer = radius * layout.scrubberOuter;
  const x1 = useTransform(spring, (a) => inner * Math.sin(a));
  const y1 = useTransform(spring, (a) => -inner * Math.cos(a));
  const x2 = useTransform(spring, (a) => outer * Math.sin(a));
  const y2 = useTransform(spring, (a) => -outer * Math.cos(a));

  if (binCount === 0 || orientation === "angular") {
    return null;
  }

  const gradient = variant === "gradient";
  const dashed = variant === "dashed";
  const showDot = showDotProp ?? !gradient;

  return (
    <g
      pointerEvents="none"
      style={{
        opacity: hidden ? 0 : 1,
        transition: "opacity 0.15s ease-out",
      }}
    >
      {gradient ? (
        <defs>
          {/* User space, following the line, so it rotates with the angle */}
          <motion.linearGradient
            gradientUnits="userSpaceOnUse"
            id={gradientId}
            x1={x1}
            x2={x2}
            y1={y1}
            y2={y2}
          >
            <stop offset="0%" stopColor={color} stopOpacity={0} />
            <stop offset="100%" stopColor={color} stopOpacity={1} />
          </motion.linearGradient>
        </defs>
      ) : null}
      <motion.line
        stroke={gradient ? `url(#${gradientId})` : color}
        strokeDasharray={dashed ? dashArray : undefined}
        strokeLinecap={dashed ? "butt" : "round"}
        strokeOpacity={lineOpacity}
        strokeWidth={strokeWidth}
        x1={x1}
        x2={x2}
        y1={y1}
        y2={y2}
      />
      {showDot ? (
        <motion.circle
          cx={x2}
          cy={y2}
          fill={color}
          r={dotRadius ?? Math.max(2.5, radius * 0.011)}
        />
      ) : null}
    </g>
  );
}

RadialScrubber.displayName = "RadialScrubber";

export default RadialScrubber;

"use client";

import { type ReactNode, useMemo } from "react";
import { cn } from "@/lib/utils";
import {
  chartCenterContainerClassName,
  chartCenterLabelClassName,
  chartCenterValueClassName,
} from "./chart-center-typography";
import { ChartStatFlow, type ChartStatFlowFormat } from "./chart-stat-flow";
import { radialNumberAt, useRadialChart } from "./radial-chart";

export interface RadialCenterState {
  /** Hovered bin, or null at rest */
  index: number | null;
  /** Hovered datum, or null at rest */
  datum: Record<string, unknown> | null;
  /** Hovered bin's x label (e.g. "09:15"), or null at rest */
  label: string | null;
  /** True when the hovered bin has no series values (future / ghost bin) */
  isFuture: boolean;
  /** Per-series totals over every non-future bin */
  totals: Record<string, number>;
  /** Per-series values of the hovered bin (0 when missing / at rest) */
  values: Record<string, number>;
}

export interface RadialCenterProps {
  /** Label under the value at rest. Default: "Total" */
  defaultLabel?: string;
  formatOptions?: ChartStatFlowFormat;
  prefix?: string;
  suffix?: string;
  className?: string;
  valueClassName?: string;
  labelClassName?: string;
  /** Full control over the center content (at rest and while hovering) */
  children?: (state: RadialCenterState) => ReactNode;
}

/**
 * Center content of {@link RadialChart}, drawn as HTML over the SVG hole
 * (same approach as `PieCenter`). Shows the sum of every series' total at
 * rest and the hovered bin's sum while scrubbing; pass `children` for custom
 * content.
 */
export function RadialCenter({
  defaultLabel = "Total",
  formatOptions,
  prefix,
  suffix,
  className,
  valueClassName = chartCenterValueClassName,
  labelClassName = chartCenterLabelClassName,
  children,
}: RadialCenterProps) {
  const { data, series, xDataKey, hoveredIndex, futureBins, totals } =
    useRadialChart();

  const state = useMemo((): RadialCenterState => {
    const datum = hoveredIndex === null ? null : (data[hoveredIndex] ?? null);
    const values: Record<string, number> = {};
    for (const s of series) {
      values[s.dataKey] = radialNumberAt(datum, s.dataKey) ?? 0;
    }
    const rawLabel = datum?.[xDataKey];
    return {
      index: hoveredIndex,
      datum,
      label: rawLabel === undefined ? null : String(rawLabel),
      isFuture:
        hoveredIndex === null ? false : Boolean(futureBins[hoveredIndex]),
      totals,
      values,
    };
  }, [data, series, xDataKey, hoveredIndex, futureBins, totals]);

  const containerClassName = cn(
    chartCenterContainerClassName,
    "flex flex-col items-center justify-center text-center",
    className
  );

  if (children) {
    return <div className={containerClassName}>{children(state)}</div>;
  }

  const source = state.datum ? state.values : state.totals;
  const value = Object.values(source).reduce((sum, v) => sum + v, 0);

  return (
    <div className={containerClassName}>
      <ChartStatFlow
        formatOptions={formatOptions}
        label={state.label ?? defaultLabel}
        labelClassName={labelClassName}
        prefix={prefix}
        suffix={suffix}
        value={value}
        valueClassName={valueClassName}
      />
    </div>
  );
}

RadialCenter.displayName = "RadialCenter";

export default RadialCenter;

"use client";

import { useMemo } from "react";
import { cn } from "@/lib/utils";
import { intFmt } from "./chart-formatters";
import { Legend } from "./legend/legend";
import { useLegendItem } from "./legend/legend-context";
import { LegendItem } from "./legend/legend-item";
import { LegendLabel } from "./legend/legend-label";
import { LegendMarker } from "./legend/legend-marker";
import { useRadialChart } from "./radial-chart";
import { radialSeriesColor } from "./radial-series-color";

function RadialLegendValue({
  formatValue,
}: {
  formatValue: (value: number) => string;
}) {
  const { series } = useRadialChart();
  const { item, index } = useLegendItem();
  const emphasize = series[index]?.emphasize;
  return (
    <span
      className="font-semibold text-foreground tabular-nums"
      style={emphasize ? { color: item.color } : undefined}
    >
      {formatValue(item.value)}
    </span>
  );
}

export interface RadialLegendProps {
  className?: string;
  /** Format the per-series totals. Default: en-US integer */
  formatValue?: (value: number) => string;
  /**
   * Show each series' total after its label. Turn off when totals are
   * meaningless (e.g. temperatures). Default: true
   */
  showValues?: boolean;
}

/**
 * Inline legend for {@link RadialChart}: dot, muted label and the series
 * total (tinted for `emphasize` series). Hovering an item sets
 * `hoveredSeries` so layers can dim the other series.
 */
export function RadialLegend({
  className,
  formatValue = intFmt,
  showValues = true,
}: RadialLegendProps) {
  const { series, totals, hoveredSeries, setHoveredSeries } = useRadialChart();
  const items = useMemo(
    () =>
      series.map((s, i) => ({
        label: s.label ?? s.dataKey,
        value: totals[s.dataKey] ?? 0,
        color: radialSeriesColor(s, i),
      })),
    [series, totals]
  );

  return (
    <Legend
      className={cn(
        "mt-2 flex-row flex-wrap items-center justify-center gap-x-3 gap-y-1",
        className
      )}
      hoveredIndex={hoveredSeries}
      items={items}
      onHoverChange={setHoveredSeries}
    >
      <LegendItem className="flex items-center gap-2">
        <LegendMarker className="size-2" />
        <LegendLabel className="text-muted-foreground text-sm" />
        {showValues ? <RadialLegendValue formatValue={formatValue} /> : null}
      </LegendItem>
    </Legend>
  );
}

RadialLegend.displayName = "RadialLegend";

export default RadialLegend;

"use client";

import NumberFlow from "@number-flow/react";
import { type ReactNode, useEffect, useMemo, useState } from "react";
import { cn } from "@/lib/utils";

/** Subset of `Intl.NumberFormatOptions` supported by NumberFlow */
export interface ChartStatFlowFormat {
  notation?: "standard" | "compact";
  compactDisplay?: "short" | "long";
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  minimumIntegerDigits?: number;
  minimumSignificantDigits?: number;
  maximumSignificantDigits?: number;
  style?: "decimal" | "percent" | "currency";
  currency?: string;
  currencyDisplay?: "symbol" | "narrowSymbol" | "code" | "name";
  unit?: string;
  unitDisplay?: "short" | "long" | "narrow";
}

export const defaultChartStatFlowFormat: ChartStatFlowFormat = {
  notation: "standard",
  maximumFractionDigits: 0,
};

function formatStatValue(
  value: number,
  formatOptions: ChartStatFlowFormat,
  prefix?: string,
  suffix?: string
): string {
  const formatted = new Intl.NumberFormat(undefined, formatOptions).format(
    value
  );
  return `${prefix ?? ""}${formatted}${suffix ?? ""}`;
}

function useNumberFlowElementReady(): boolean {
  const [ready, setReady] = useState(
    () =>
      typeof customElements !== "undefined" &&
      Boolean(customElements.get("number-flow-react"))
  );

  useEffect(() => {
    if (ready) {
      return;
    }
    let cancelled = false;
    customElements.whenDefined("number-flow-react").then(() => {
      if (!cancelled) {
        setReady(true);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [ready]);

  return ready;
}

export interface ChartStatFlowProps {
  value: number;
  label: string;
  formatOptions?: ChartStatFlowFormat;
  prefix?: string;
  suffix?: string;
  valueClassName?: string;
  labelClassName?: string;
  icon?: ReactNode;
}

/**
 * Shared value + label stack using NumberFlow (same layout as pie / ring centers).
 * Parent should provide flex alignment and sizing when needed.
 */
export function ChartStatFlow({
  value,
  label,
  formatOptions = defaultChartStatFlowFormat,
  prefix,
  suffix,
  valueClassName = "text-2xl font-bold",
  labelClassName = "text-xs",
  icon,
}: ChartStatFlowProps) {
  const numberFlowReady = useNumberFlowElementReady();
  const staticValue = useMemo(
    () => formatStatValue(value, formatOptions, prefix, suffix),
    [value, formatOptions, prefix, suffix]
  );

  return (
    <>
      {icon ? (
        <div className="mb-2 flex h-12 w-12 items-center justify-center rounded-full bg-muted/50">
          {icon}
        </div>
      ) : null}
      <span className={cn("text-foreground tabular-nums", valueClassName)}>
        {numberFlowReady ? (
          <NumberFlow
            format={formatOptions}
            isolate
            prefix={prefix}
            suffix={suffix}
            value={value}
            willChange
          />
        ) : (
          staticValue
        )}
      </span>
      <span className={cn("mt-0.5 text-chart-label", labelClassName)}>
        {label}
      </span>
    </>
  );
}

ChartStatFlow.displayName = "ChartStatFlow";

/**
 * Fluid typography for pie / ring / gauge center labels.
 *
 * Uses CSS container query units (`cqw`) so values scale with the center
 * hole — not the viewport — which keeps stat text readable on small charts.
 */
export const chartCenterContainerClassName =
  "@container/chart-center size-full min-w-0";

/** Primary stat — ~22% of center width, clamped between text-sm and text-3xl. */
export const chartCenterValueClassName =
  "font-bold tabular-nums leading-none text-[clamp(0.75rem,22cqw,1.875rem)]";

/** Supporting label — ~9% of center width, clamped between 10px and text-xs. */
export const chartCenterLabelClassName =
  "max-w-full truncate leading-tight text-[clamp(0.625rem,9cqw,0.75rem)]";

"use client";

import type { ReactNode } from "react";
import { PatternCircles, PatternLines } from "./visx-pattern";

export const PATTERN_PRESET_IDS = [
  "none",
  "diagonal",
  "horizontal",
  "vertical",
  "cross",
  "dots",
  "circles",
  "accent",
] as const;

export type PatternPresetId = (typeof PATTERN_PRESET_IDS)[number];

export interface PatternPresetOptions {
  color?: string;
  scale?: number;
  strokeWidth?: number;
  radius?: number;
  complement?: boolean;
  fill?: string;
  /** Dot grid only — when false, render hollow dots (stroke only). Default: true */
  dotFill?: boolean;
  tileBackground?: string;
}

/** Presets rendered with @visx/pattern `PatternCircles`. */
export function isCirclePattern(preset: PatternPresetId): boolean {
  return preset === "circles" || preset === "dots";
}

/** @deprecated Use `isCirclePattern`. */
export function isCirclesPattern(preset: PatternPresetId): boolean {
  return isCirclePattern(preset);
}

export function patternPresetTileSize(
  preset: PatternPresetId,
  scale = 1
): { width: number; height: number; strokeWidth: number } {
  let base = { width: 6, height: 6, strokeWidth: 1 };
  if (preset === "dots") {
    base = { width: 10, height: 10, strokeWidth: 0 };
  } else if (preset === "cross") {
    base = { width: 8, height: 8, strokeWidth: 1 };
  } else if (preset === "circles") {
    base = { width: 6, height: 6, strokeWidth: 1 };
  }

  return {
    width: base.width * scale,
    height: base.height * scale,
    strokeWidth: base.strokeWidth * scale,
  };
}

function renderPatternCircles(
  preset: "dots" | "circles",
  _id: string,
  color: string,
  common: {
    id: string;
    height: number;
    width: number;
    strokeWidth: number;
    background?: string;
  },
  options: PatternPresetOptions,
  scale: number
) {
  const isDotGrid = preset === "dots";
  const radius =
    options.radius ?? (isDotGrid ? Math.max(0.5, 1.5 * scale) : 2 * scale);
  const dotFillEnabled = options.dotFill !== false;

  if (isDotGrid) {
    const dotFill = dotFillEnabled ? options.fill || color : undefined;
    return (
      <PatternCircles
        {...common}
        complement={options.complement}
        fill={dotFill}
        radius={radius}
        stroke={dotFillEnabled && options.fill ? undefined : color}
        strokeWidth={
          dotFillEnabled && !options.fill
            ? (options.strokeWidth ?? 0)
            : (options.strokeWidth ?? 1)
        }
      />
    );
  }

  return (
    <PatternCircles
      {...common}
      complement={options.complement}
      fill={options.fill || undefined}
      radius={radius}
      stroke={color}
      strokeWidth={options.strokeWidth ?? common.strokeWidth}
    />
  );
}

/** Renders a @visx/pattern definition node for the given preset. */
export function renderPatternPreset(
  preset: PatternPresetId,
  id: string,
  options: PatternPresetOptions = {}
): ReactNode {
  if (preset === "none") {
    return null;
  }

  const color = options.color ?? "var(--chart-1)";
  const scale = options.scale ?? 1;
  const tile = patternPresetTileSize(preset, scale);
  const common = {
    id,
    height: tile.height,
    width: tile.width,
    strokeWidth: tile.strokeWidth,
    ...(options.tileBackground ? { background: options.tileBackground } : {}),
  };

  if (preset === "dots" || preset === "circles") {
    return renderPatternCircles(preset, id, color, common, options, scale);
  }

  const strokeWidth = options.strokeWidth ?? tile.strokeWidth;

  switch (preset) {
    case "diagonal":
      return (
        <PatternLines
          {...common}
          orientation={["diagonal"]}
          stroke={color}
          strokeWidth={strokeWidth}
        />
      );
    case "horizontal":
      return (
        <PatternLines
          {...common}
          orientation={["horizontal"]}
          stroke={color}
          strokeWidth={strokeWidth}
        />
      );
    case "vertical":
      return (
        <PatternLines
          {...common}
          orientation={["vertical"]}
          stroke={color}
          strokeWidth={strokeWidth}
        />
      );
    case "cross":
      return (
        <PatternLines
          {...common}
          orientation={["diagonal", "diagonalRightToLeft"]}
          stroke={color}
          strokeWidth={strokeWidth}
        />
      );
    case "accent":
      return (
        <PatternLines
          {...common}
          orientation={["diagonal"]}
          stroke="#e879f9"
          strokeWidth={strokeWidth}
        />
      );
    default:
      return null;
  }
}

